-- Dropdown Terminal (kitty-dropterm)

hl.window_rule({
    name  = "kitty-dropterm",
    match = {
        class = "^(kitty-dropterm)$",
    },
    float = true,
    size = { "(monitor_w*0.65)", "(monitor_h*0.55)" },
    move = { "(monitor_w*0.175)", 30 },
    dim_around = true,
    animation = "slide top",
})

